 public:
  enum PriorityValue {
    PRIORITY_LOW = 1,
    PRIORITY_NORMAL,
    PRIORITY_HIGH
  };




  enum {
    PRIORITY_MASK = 0x03,
    SYNC_BIT = 0x04,
    REPLY_BIT = 0x08,
    REPLY_ERROR_BIT = 0x10,
    UNBLOCK_BIT = 0x20,
    PUMPING_MSGS_BIT = 0x40,
    HAS_SENT_TIME_BIT = 0x80,
  };

  ~Message() override;

  Message();



