void LinkToTextMenuObserver::InitMenu(
    const content::ContextMenuParams& params) {
  open_from_new_selection_ = !params.selection_text.empty();
  raw_url_ = params.page_url;
  if (params.page_url.has_ref()) {
    url_ = shared_highlighting::RemoveFragmentSelectorDirectives(raw_url_);
  } else {
    url_ = params.page_url;
  }
  annotation_type_ = params.annotation_type;





  if (open_from_new_selection_) {
    proxy_->AddMenuItem(
        50158,
        l10n_util::GetStringUTF16((::ui::AllowlistedResource<10150>(), 10150)));
    RequestLinkGeneration();
  } else if (annotation_type_.has_value()) {
    switch (annotation_type_.value()) {
      case blink::mojom::AnnotationType::kSharedHighlight:
        proxy_->AddMenuItem(
            50159,
            l10n_util::GetStringUTF16((::ui::AllowlistedResource<10153>(), 10153)));
        proxy_->AddMenuItem(
            50160,
            l10n_util::GetStringUTF16((::ui::AllowlistedResource<10152>(), 10152)));
        break;
      case blink::mojom::AnnotationType::kGlic:
        proxy_->AddMenuItem(
            50160,
            l10n_util::GetStringUTF16((::ui::AllowlistedResource<10152>(), 10152)));
        break;
      case blink::mojom::AnnotationType::kTextFinder:
      case blink::mojom::AnnotationType::kUserNote:
        true ? (void)0 : ::logging::VoidifyStream() & (*::logging::g_swallow_stream);
    }
  }
}

bool LinkToTextMenuObserver::IsCommandIdSupported(int command_id) {
  return command_id == 50158 ||
         command_id == 50160 ||
         command_id == 50159;
}

bool LinkToTextMenuObserver::IsCommandIdEnabled(int command_id) {

  true ? (void)0 : ::logging::VoidifyStream(!(IsCommandIdSupported(command_id))) & (*::logging::g_swallow_stream);



  if (open_from_new_selection_) {
    return generated_link_.has_value();
  }


  return true;
}

void LinkToTextMenuObserver::ExecuteCommand(int command_id) {

  true ? (void)0 : ::logging::VoidifyStream(!(IsCommandIdSupported(command_id))) & (*::logging::g_swallow_stream);

  if (command_id == 50158) {
    ExecuteCopyLinkToText();
  } else if (command_id == 50159) {
    ReshareLink();
  } else if (command_id == 50160) {
    RemoveHighlights();
  }
}

